#!/bin/bash\n# Telegram Webhook 测试脚本\n\n# 配置\nHOST=\"localhost\"\nPORT=\"8000\"\nBASE_URL=\"http://${HOST}:${PORT}/api/settings\"\n\n# 测试 Webhook 端点\necho \"测试 Telegram Webhook 端点...\"\necho \"==================================\"\n\ncurl -X POST \"${BASE_URL}/notifications/telegram/webhook\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"update_id\": 123456789,\n    \"message\": {\n      \"message_id\": 123,\n      \"from\": {\n        \"id\": 987654321,\n        \"is_bot\": false,\n        \"first_name\": \"TestUser\",\n        \"language_code\": \"zh-CN\"\n      },\n      \"chat\": {\n        \"id\": 987654321,\n        \"type\": \"private\",\n        \"first_name\": \"TestUser\"\n      },\n      \"date\": 1699999999,\n      \"text\": \"/start\"\n    }\n  }'\n\necho \"\"\necho \"\"\n\n# 测试获取发现的 Chat ID\necho \"获取发现的 Chat ID...\"\necho \"==================================\"\ncurl -X GET \"${BASE_URL}/notifications/telegram/discovered_chat_ids\"\n\necho \"\"\necho \"\"\necho \"测试完成!\"\n